128	/** The refusals that are decisions on a well-formed request from a player in the match, and so are kept (§16). */
129	export const RECORDED_REFUSALS = ["insufficient-gold", "tonic-limit", "player-in-duel", "player-disconnected"] as const;
130	export type RecordedRefusal = (typeof RECORDED_REFUSALS)[number];
131	
132	/** At most this many refusals are kept per player; the oldest goes first, and its id is then evaluated afresh. */
133	export const MAX_RECORDED_REFUSALS = 16;
