192	  /**
193	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
194	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
195	   */
196	  override onJoin(client: Client, options: unknown): void {
197	    this.admit(options);
198	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
199	    this.gates.set(client.sessionId, new InputGate());
200	    client.view = new StateView();
201	    this.mirror();
202	  }
